import { useEffect, useState } from "react";

export type Theme = "light" | "dark" | "auto";
export type ViewMode = "source" | "preview" | "split";

const KEY = "md-studio-session-v1";

export interface SessionApi {
  theme: Theme;
  viewMode: ViewMode;
  setTheme: (t: Theme) => void;
  setViewMode: (v: ViewMode) => void;
}

export function useSession(): SessionApi {
  const [theme, setThemeState] = useState<Theme>("auto");
  const [viewMode, setViewModeState] = useState<ViewMode>("split");

  useEffect(() => {
    try {
      const raw = localStorage.getItem(KEY);
      if (!raw) return;
      const parsed = JSON.parse(raw) as { theme?: Theme; viewMode?: ViewMode };
      if (parsed.theme) setThemeState(parsed.theme);
      if (parsed.viewMode) setViewModeState(parsed.viewMode);
    } catch {
      /* ignore */
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(KEY, JSON.stringify({ theme, viewMode }));
  }, [theme, viewMode]);

  return {
    theme,
    viewMode,
    setTheme: setThemeState,
    setViewMode: setViewModeState,
  };
}
